// Generates the web and mobile token files from design-system/tokens.json.
// Run with `pnpm tokens` after the design system changes. Do not edit the outputs by hand.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(resolve(root, 'design-system/tokens.json'), 'utf8'));
const banner = 'Generated by scripts/build-tokens.mjs from design-system/tokens.json. Do not edit.';

const themeIds = tokens.color.themes.map((theme) => theme.id);
const colorByName = new Map(tokens.color.tokens.map((token) => [token.name, token.value]));

function resolveColor(name, theme, seen = []) {
  if (seen.includes(name)) throw new Error(`Colour alias loop: ${[...seen, name].join(' -> ')}`);
  const value = colorByName.get(name);
  if (value === undefined) throw new Error(`Unknown colour token: ${name}`);
  const themed = typeof value === 'string' ? value : value[theme];
  const alias = /^\{(.+)\}$/.exec(themed);
  return alias ? resolveColor(alias[1], theme, [...seen, name]) : themed;
}

const colors = Object.fromEntries(
  themeIds.map((theme) => [
    theme,
    Object.fromEntries(tokens.color.tokens.map((token) => [token.name, resolveColor(token.name, theme)])),
  ]),
);
const shadows = Object.fromEntries(
  themeIds.map((theme) => [
    theme,
    Object.fromEntries(
      tokens.shadow.tokens.map((token) => [token.name, typeof token.value === 'string' ? token.value : token.value[theme]]),
    ),
  ]),
);
const typeStyles = tokens.type.groups.flatMap((group) =>
  group.styles.map((style) => ({ ...style, family: group.family })),
);
const px = (value) => {
  const match = /^(-?\d+(?:\.\d+)?)px$/.exec(value);
  if (!match) throw new Error(`Expected a px value, got ${value}`);
  return Number(match[1]);
};
const camel = (name) => name.replace(/-([a-z0-9])/g, (_, char) => char.toUpperCase());

// ---------- web: apps/web/src/styles/tokens.css ----------

const webOut = resolve(root, 'apps/web/src/styles/tokens.css');
const fontUrl = (file) => relative(dirname(webOut), resolve(root, 'design-system', file));
const declarations = (entries, indent = '  ') =>
  Object.entries(entries)
    .map(([name, value]) => `${indent}--${name}: ${value};`)
    .join('\n');
const themeVars = (theme) => ({ ...colors[theme], ...shadows[theme] });
const staticVars = Object.fromEntries(
  [...tokens.spacing.tokens, ...tokens.size.tokens].map((token) => [token.name, token.value]),
);
const spacingSteps = Object.fromEntries(
  tokens.spacing.tokens.map((token) => [`spacing-${token.name.replace('space-', '')}`, token.value]),
);
const sizeSteps = Object.fromEntries(
  tokens.size.tokens.map((token) => [`spacing-${token.name.replace('-width', '')}`, token.value]),
);

const css = `/* ${banner} */

${tokens.type.fonts
  .map(
    (font) => `@font-face {
  font-family: "${font.family}";
  src: url("${fontUrl(font.file)}") format("woff2");
  font-weight: ${font.weight};
  font-style: ${font.style};
  font-display: swap;
}`,
  )
  .join('\n\n')}

/* Design-system variables under their own names, so design-system/components/bundle.css works unchanged. */
:root {
${declarations(themeVars('light'))}
${declarations(staticVars)}
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
${declarations(themeVars('dark'), '    ')}
    color-scheme: dark;
  }
}

[data-theme="light"] {
${declarations(themeVars('light'))}
  color-scheme: light;
}

[data-theme="dark"] {
${declarations(themeVars('dark'))}
  color-scheme: dark;
}

/* Tailwind theme: only the design system's values exist. */
@theme static {
  --color-*: initial;
  --spacing: initial;
  --radius-*: initial;
  --shadow-*: initial;
  --text-*: initial;
  --font-*: initial;
  --font-weight-*: initial;

${declarations(Object.fromEntries(Object.entries(tokens.type.families).map(([name, value]) => [`font-${name}`, value])))}
  --font-weight-normal: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  --spacing-0: 0px;
${declarations(spacingSteps)}
${declarations(sizeSteps)}

${declarations(Object.fromEntries(tokens.radius.tokens.map((token) => [token.name, token.value])))}
}

/* Colours point at the variables above so they follow data-theme on any ancestor. */
@theme inline {
${declarations(Object.fromEntries(tokens.color.tokens.map((token) => [`color-${token.name}`, `var(--${token.name})`])))}
}

${tokens.shadow.tokens
  .map((token) => `@utility ${token.name} {\n  box-shadow: var(--${token.name});\n}`)
  .join('\n\n')}

/* One utility per type style: family, size, line height, weight and tracking together. */
${typeStyles
  .map((style) => {
    const lines = [
      `font-family: var(--font-${style.family});`,
      `font-size: ${style.fontSize};`,
      `line-height: ${style.lineHeight};`,
      `font-weight: ${style.fontWeight};`,
      style.letterSpacing ? `letter-spacing: ${style.letterSpacing};` : null,
      style.family === 'mono' ? 'font-variant-numeric: tabular-nums;' : null,
    ].filter(Boolean);
    return `@utility type-${style.name} {\n${lines.map((line) => `  ${line}`).join('\n')}\n}`;
  })
  .join('\n\n')}
`;
writeFileSync(webOut, css);

// ---------- mobile: apps/mobile/src/theme/tokens.ts ----------

// PostScript names of the static TTFs in apps/mobile/assets/fonts, which is how iOS finds them.
const fontFile = { sans: 'AtkinsonHyperlegibleNext', mono: 'AtkinsonHyperlegibleMono' };
const weightName = { 400: 'Regular', 500: 'Medium', 600: 'SemiBold' };
const fontFamily = (family, weight) => {
  if (!weightName[weight]) throw new Error(`No font file for weight ${weight}`);
  return `${fontFile[family]}-${weightName[weight]}`;
};

const mobileType = Object.fromEntries(
  typeStyles.map((style) => {
    const fontSize = px(style.fontSize);
    const em = style.letterSpacing ? Number(/^(-?[\d.]+)em$/.exec(style.letterSpacing)[1]) : 0;
    return [
      camel(style.name),
      {
        fontFamily: fontFamily(style.family, style.fontWeight),
        fontSize,
        lineHeight: px(style.lineHeight),
        ...(em ? { letterSpacing: Number((em * fontSize).toFixed(2)) } : {}),
        ...(style.family === 'mono' ? { fontVariant: ['tabular-nums'] } : {}),
      },
    ];
  }),
);
const camelKeys = (object) => Object.fromEntries(Object.entries(object).map(([key, value]) => [camel(key), value]));
const numberTokens = (list) => Object.fromEntries(list.map((token) => [camel(token.name), px(token.value)]));
const literal = (value) => JSON.stringify(value, null, 2);

const ts = `// ${banner}
import type { TextStyle } from 'react-native';

export type ThemeName = ${themeIds.map((id) => `'${id}'`).join(' | ')};

export const colors = ${literal(Object.fromEntries(themeIds.map((theme) => [theme, camelKeys(colors[theme])])))} as const;

export type ColorName = keyof (typeof colors)['light'];

/** Font family names as iOS registers them, by family and weight. */
export const fonts = ${literal(
  Object.fromEntries(
    Object.keys(fontFile).map((family) => [
      family,
      Object.fromEntries(Object.keys(weightName).map((weight) => [weight, fontFamily(family, weight)])),
    ]),
  ),
)} as const;

/** Type styles, in points. Spread one into a Text style. */
export const type = ${literal(mobileType)} as const satisfies Record<string, TextStyle>;

export type TypeName = keyof typeof type;

export const space = ${literal(numberTokens(tokens.spacing.tokens))} as const;

export const radius = ${literal(numberTokens(tokens.radius.tokens))} as const;

export const size = ${literal(numberTokens(tokens.size.tokens))} as const;

/** For the boxShadow style of things that float: sheets and the push banner only. */
export const shadow = ${literal(Object.fromEntries(themeIds.map((theme) => [theme, camelKeys(shadows[theme])])))} as const;
`;
writeFileSync(resolve(root, 'apps/mobile/src/theme/tokens.ts'), ts);

console.log('Wrote apps/web/src/styles/tokens.css and apps/mobile/src/theme/tokens.ts');
